import{a as e,i as t,r as n,t as r}from"./app-Dkwa1Gla.js";var i=JSON.parse(`{"path":"/%E7%AC%AC06%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E7%AE%A1%E7%90%86%E6%A6%82%E8%AE%BA/6.3%20%E9%A1%B9%E7%9B%AE%E7%BB%8F%E7%90%86%E8%81%8C%E8%B4%A3.html","title":"6.3 项目经理职责","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第06章 项目管理概论/6.3 项目经理职责.md"}`),a={name:`6.3 项目经理职责.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_6-3-项目经理职责" tabindex="-1"><a class="header-anchor" href="#_6-3-项目经理职责"><span>6.3 项目经理职责</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>项目经理是负责项目计划、执行和控制的核心人物，对项目的成功负责。</p><h2 id="主要职责" tabindex="-1"><a class="header-anchor" href="#主要职责"><span>主要职责</span></a></h2><h3 id="_1-项目规划" tabindex="-1"><a class="header-anchor" href="#_1-项目规划"><span>1. 项目规划</span></a></h3><ul><li>制定项目计划</li><li>明确项目目标和范围</li><li>制定进度和预算计划</li></ul><h3 id="_2-团队管理" tabindex="-1"><a class="header-anchor" href="#_2-团队管理"><span>2. 团队管理</span></a></h3><ul><li>组建项目团队</li><li>分配任务和职责</li><li>激励团队成员</li></ul><h3 id="_3-进度控制" tabindex="-1"><a class="header-anchor" href="#_3-进度控制"><span>3. 进度控制</span></a></h3><ul><li>监控项目进度</li><li>识别进度偏差</li><li>采取纠正措施</li></ul><h3 id="_4-成本控制" tabindex="-1"><a class="header-anchor" href="#_4-成本控制"><span>4. 成本控制</span></a></h3><ul><li>监控项目成本</li><li>控制成本超支</li><li>优化资源配置</li></ul><h3 id="_5-质量管理" tabindex="-1"><a class="header-anchor" href="#_5-质量管理"><span>5. 质量管理</span></a></h3><ul><li>确保项目质量</li><li>实施质量保证</li><li>处理质量问题</li></ul><h3 id="_6-风险管理" tabindex="-1"><a class="header-anchor" href="#_6-风险管理"><span>6. 风险管理</span></a></h3><ul><li>识别项目风险</li><li>制定风险应对计划</li><li>监控风险状态</li></ul><h3 id="_7-沟通管理" tabindex="-1"><a class="header-anchor" href="#_7-沟通管理"><span>7. 沟通管理</span></a></h3><ul><li>管理项目沟通</li><li>定期汇报项目进展</li><li>协调利益相关方</li></ul><h3 id="_8-变更管理" tabindex="-1"><a class="header-anchor" href="#_8-变更管理"><span>8. 变更管理</span></a></h3><ul><li>管理项目变更</li><li>评估变更影响</li><li>审批变更请求</li></ul><h2 id="能力要求" tabindex="-1"><a class="header-anchor" href="#能力要求"><span>能力要求</span></a></h2><h3 id="技术能力" tabindex="-1"><a class="header-anchor" href="#技术能力"><span>技术能力</span></a></h3><ul><li>掌握项目管理知识</li><li>了解项目相关技术</li></ul><h3 id="管理能力" tabindex="-1"><a class="header-anchor" href="#管理能力"><span>管理能力</span></a></h3><ul><li>计划和组织能力</li><li>决策和问题解决能力</li></ul><h3 id="领导能力" tabindex="-1"><a class="header-anchor" href="#领导能力"><span>领导能力</span></a></h3><ul><li>激励团队能力</li><li>冲突解决能力</li></ul><h3 id="沟通能力" tabindex="-1"><a class="header-anchor" href="#沟通能力"><span>沟通能力</span></a></h3><ul><li>口头和书面沟通</li><li>跨部门协调能力</li></ul><h3 id="战略能力" tabindex="-1"><a class="header-anchor" href="#战略能力"><span>战略能力</span></a></h3><ul><li>理解组织战略</li><li>Align项目目标与战略</li></ul><h2 id="项目经理的角色" tabindex="-1"><a class="header-anchor" href="#项目经理的角色"><span>项目经理的角色</span></a></h2><h3 id="领导者" tabindex="-1"><a class="header-anchor" href="#领导者"><span>领导者</span></a></h3><ul><li>为项目指明方向</li><li>激励团队成员</li></ul><h3 id="管理者" tabindex="-1"><a class="header-anchor" href="#管理者"><span>管理者</span></a></h3><ul><li>执行项目计划</li><li>控制项目进展</li></ul><h3 id="协调者" tabindex="-1"><a class="header-anchor" href="#协调者"><span>协调者</span></a></h3><ul><li>协调各方利益</li><li>解决冲突</li></ul><h3 id="沟通者" tabindex="-1"><a class="header-anchor" href="#沟通者"><span>沟通者</span></a></h3><ul><li>传递项目信息</li><li>建立沟通渠道</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>项目经理的主要职责</strong></li><li><strong>项目经理的能力要求</strong></li><li><strong>项目经理的角色</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>规划团队进度成本质量风险沟通变更，项目经理全负责</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：以下哪项不是项目经理的职责？ A. 制定项目计划 B. 执行项目任务 C. 管理项目团队 D. 负责具体技术实现</p><p><strong>答案</strong>：D</p><p><strong>解析</strong>：项目经理主要负责项目的规划、管理和协调，具体技术实现通常由项目团队成员负责。项目经理不需要亲自负责具体技术实现。</p>`,48)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};